Parse SH1 for every `INVOICE NO` header and take the value directly below it, preserving row order. Scan DATA rows 2-20, starting a new SH1 invoice at the first row after a TOTAL when column E is SH1, and fill that invoice through the TOTAL row. Leave all unmatched or invoice-exhausted rows with their original D values.

```python
import shutil
import openpyxl

shutil.copy(INIT, OUT)

vals = openpyxl.load_workbook(INIT, data_only=True)
wb = openpyxl.load_workbook(OUT)

TARGET = "SH1"

def clean(v):
    if v is None:
        return None
    if isinstance(v, str):
        s = v.strip()
        return s if s else None
    return v

def get_invoices(sheet_name):
    if sheet_name not in vals.sheetnames:
        return []
    vws = vals[sheet_name]
    out = []
    for row in vws.iter_rows():
        for cell in row:
            if cell.value is not None and str(cell.value).strip().upper() == "INVOICE NO":
                below = clean(vws.cell(row=cell.row + 1, column=cell.column).value)
                if below is not None:
                    out.append(below)
    return out

invoices = get_invoices(TARGET)

if "DATA" not in wb.sheetnames:
    wb.create_sheet("DATA")

dsrc = vals["DATA"] if "DATA" in vals.sheetnames else None
dout = wb["DATA"]

current = None
idx = 0

for r in range(2, 21):
    if dsrc is None:
        e = None
        a = None
        orig = None
    else:
        e = clean(dsrc.cell(row=r, column=5).value)
        a = clean(dsrc.cell(row=r, column=1).value)
        orig = dsrc.cell(row=r, column=4).value

    if e is not None and str(e).strip().upper() == TARGET.upper():
        if current is None:
            if idx < len(invoices):
                current = invoices[idx]
                idx += 1
            else:
                current = None

        val = current if current is not None else clean(orig)

        if a is not None and str(a).strip().upper() == "TOTAL":
            current = None
    else:
        current = None
        val = clean(orig)

    dout.cell(row=r, column=4, value=val)

wb.save(OUT)

print("invoices:", invoices)
print("D2:D20:", [dout.cell(row=r, column=4).value for r in range(2, 21)])
